type Getters<T> = { [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K] };
// Getters<{ name: string }>  // ^? { getName: () => string }

// Сужает K до его строковой части через `string & K` (или ограничивает ключи T до string) перед передачей в Capitalize.

model.en:
type OmitByValue<T, V> = { [K in keyof T as T[K] extends V ? never : K]: T[K] };
// OmitByValue<{ a: string; b: number; c: string }, string>  // ^? { b: number }

// Uses `as T[K] extends V ? never : K` so keys whose value matches V remap to never and are dropped, the rest survive.

model.ru:
type OmitByValue<T, V> = { [K in keyof T as T[K] extends V ? never : K]: T[K] };
// OmitByValue<{ a: string; b: number; c: string }, string>  // ^? { b: number }

// Использует `as T[K] extends V ? never : K`, чтобы ключи со значением, совпадающим с V, ремаппились в never и удалялись, а остальные выживали.
